function separate_paren_groups(paren_string: string): string[] {
  const result: string[] = [];
  let i = 0;
  let n = paren_string.length;

  while (i < n) {
    const open = paren_string[i];
    const close = paren_string[i + 1];

    if (open === '(' && close === ')') {
      // Found a balanced pair
      result.push(paren_string.slice(i + 2));
      i += 2;
    } else if (open === '(') {
      // Found an open parenthesis, but not a closing one
      result.push(paren_string.slice(i, i + 1));
      i++;
    } else if (open === ')') {
      // Found a closing parenthesis, but not an open one
      result.push(paren_string.slice(i, i + 1));
      i++;
    } else {
      // Unexpected character
      result.push(paren_string.slice(i, i + 1));
      i++;
    }
  }

  return result;
}
