function make_palindrome(string: string): string {
  if (string.length === 0) return "";
  if (string.length === 1) return string;

  const n = string.length;
  let i = 0;
  let j = n - 1;

  while (i < j) {
    if (string[i] === string[j]) {
      i++;
      j--;
    } else {
      break;
    }
  }

  if (i === j) {
    return string;
  }

  const prefix = string.substring(0, i);
  const suffix = string.substring(i + 1, n);
  const reverseSuffix = suffix.split("").reverse().join("");

  return prefix + reverseSuffix;
}
