function find_closest_elements(numbers: number[]): [number, number] {
  if (numbers.length < 2) {
    throw new Error("Array must contain at least two elements");
  }

  const min = numbers[0];
  const max = numbers[1];

  for (let i = 2; i < numbers.length; i++) {
    const current = numbers[i];
    if (current < min) {
      min = current;
    } else if (current > max) {
