function sort_array(array: number[]): number[] {
  if (array.length === 0) return [];
  if (array.length === 1) return [array[0]];

  const sum = (a: number, b: number) => a + b;
  const isOddSum = (a: number, b: number) => sum(a, b) % 2 === 1;
  const isEvenSum = (a: number, b: number) => sum(a, b) % 2 === 0;

  let left = 0, right = array.length - 1;
  let result: number[] = [];

  while (left <= right) {
    const mid = (left + right) / 2;
    const midVal = array[mid];

    if (isOddSum(midVal, midVal)) {
      result.push(midVal);
      left = mid + 1;
    } else {
      result.push(midVal);
      right = mid - 1;
    }
  }

  return result;
}
