function minPath(grid: number[][], k: number): number[] {
  if (k <= 0) return [];
  if (grid.length === 0 || grid[0].length === 0) return [];

  const n = grid.length;
  const rows = grid.map((row) => row.length);
  const col = rows.map((r) => r);

  // Build adjacency list for the grid
  const adj: Map<number, number[]> = new Map();
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < col[i]; j++) {
      adj.set(i, [...adj.get(i), j]);
    }
  }

  // BFS to find the shortest path of length k
  const queue: number[] = [];
  const visited: Set<number> = new Set();
  queue.push(0);
  visited.add(0);

  while (queue.length > 0) {
    const current = queue.shift()!;
    const neighbors = adj.get(current) || [];

    for (const neighbor of neighbors) {
      if (visited.has(neighbor)) continue;
      visited.add(neighbor);
      queue.push(neighbor);
    }
  }

  if (k === 0) return [];

  // BFS to find the lexicographically smallest path of length k
  const queue: number[] = [];
  const visited: Set<number> = new Set();
  queue.push(0);
  visited.add(0);

  while (queue.length > 0) {
    const current = queue.shift()!;
    const neighbors = adj.get(current) || [];

    for (const neighbor of neighbors) {
      if (visited.has(neighbor)) continue;
      visited.add(neighbor);
      queue.push(neighbor);
    }
  }

  // Reconstruct the path
  const path: number[] = [];
  let current = 0;
  while (current < k) {
    const neighbor = adj.get(current) || [];
    const next = neighbor[0];
    path.push(next);
    current = next;
  }

  return path;
}
