// return 'Slices.SErviNGSliCes' since 'SErviNGSliCes' is the strongest extension 
// (its strength is -1).
// Example:
// >>> Strongest_Extension("my_class", ["AA", "Be", "CC"])
// "my_class.AA"
function Strongest_Extension(class_name: string, extensions: string[]): string {
  const strengthMap: Record<string, number> = {};
  for (const ext of extensions) {
    const CAP = ext.match(/[A-Z]/g).length;
    const SM = ext.match(/[a-z]/g).length;
    const strength = CAP - SM;
    strengthMap[ext] = strength;
  }

  const strongest = Object.entries(strengthMap).sort((a, b) => a[1] - b[1])[0];
  return `${class_name}.${strongest}`;
}


