function do_algebra(operator: string[], operand: number[]): number {
  const n = operand.length;
  if (n < 2) return 0;
  const opIndex = operator.indexOf('+');
  if (opIndex === -1) return 0;
  const op = operator[opIndex];
  const left = operand.slice(0, opIndex + 1);
  const right = operand.slice(opIndex + 1);
  const res = left.reduce((acc, num) => {
    if (op === '+') return acc + num;
    if (op === '-') return acc - num;
    if (op === '*') return acc * num;
    if (op === '/') {
      if (num < 0) return 0;
      return Math.floor(acc / num);
    }
    if (op === '**') return Math.pow(acc, num);
    return acc;
  }, 0);
  return res;
}
